    /// <summary>bits bits of v from bit offset, at the bottom of the result: sign-extended for a signed type.</summary>
    public static int BitfieldExtract(int v, int offset, int bits)
    {
        if (bits <= 0) return 0;
        uint u = (uint)v;
        uint f = bits >= 32 ? u >> offset : (u >> offset) & ((1u << bits) - 1u);
        if (bits < 32 && ((f >> (bits - 1)) & 1u) != 0) return (int)(f | ~((1u << bits) - 1u));
        return (int)f;
    }
