    /// <summary>The bits in reverse order.</summary>
    public static int BitfieldReverse(int v)
    {
        uint u = (uint)v, r = 0;
        for (int i = 0; i < 32; ++i, u >>= 1) r = (r << 1) | (u & 1u);
        return unchecked((int)r);
    }
