    /// <summary>x + y, and in carry whether it overflowed.</summary>
    public static uint UaddCarry(uint x, uint y, out uint carry)
    {
        uint s = x + y;
        carry = s < x ? 1u : 0u;
        return s;
    }
    public static UVec2 UaddCarry(UVec2 x, UVec2 y, out UVec2 carry)
    {
