    public static uint PackUnorm4x8(Vec4 v) => ((uint)RoundAwayToInt(Clamp(v.X, 0f, 1f) * 255f) << 0) | ((uint)RoundAwayToInt(Clamp(v.Y, 0f, 1f) * 255f) << 8) | ((uint)RoundAwayToInt(Clamp(v.Z, 0f, 1f) * 255f) << 16) | ((uint)RoundAwayToInt(Clamp(v.W, 0f, 1f) * 255f) << 24);
