    /// <summary>The unsigned angle between two vectors, in radians.</summary>
    public static float Angle(Vec2 a, Vec2 b)
    {
        var denom = float.Sqrt((Length2(a) * Length2(b)));
        return ((denom > 0f) ? float.Acos(Clamp((Dot(a, b) / denom), -1f, 1f)) : 0f);
    }
