    /// <summary>A critically damped spring toward target: frame-rate independent, never overshoots. velocity is its state.</summary>
    public static float SmoothDamp(float current, float target, ref float velocity, float smoothTime, float deltaTime, float maxSpeed = float.PositiveInfinity)
    {
        smoothTime = Max(0.0001f, smoothTime);
        var omega = 2f / smoothTime;
        var x = omega * deltaTime;
        var exp = 1f / (1f + x + 0.48f * x * x + 0.235f * x * x * x);
        var maxChange = maxSpeed * smoothTime;
        var change = Clamp(current - target, -maxChange, maxChange);
        var clampedTarget = current - change;
        var temp = (velocity + omega * change) * deltaTime;
        velocity = (velocity - omega * temp) * exp;
        var output = clampedTarget + (change + temp) * exp;
        if ((target - current > 0f) == (output > target)) { output = target; velocity = (output - target) / deltaTime; }
        return output;
    }
